from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    splits=[]
    if w%2==1:
        j=w//2
        if all(row[j]==grid[0][j] for row in grid):
            splits.append(('v',j))
    if h%2==1:
        i=h//2
        if all(x==grid[i][0] for x in grid[i]):
            splits.append(('h',i))
    if not splits:
        raise ValueError('no equal split separator')
    axis,k=splits[0]
    if axis=='v':
        a=[row[:k] for row in grid]
        b=[row[k+1:] for row in grid]
    else:
        a=grid[:k]
        b=grid[k+1:]
    ca=set(x for row in a for x in row)
    cb=set(x for row in b for x in row)
    shared=ca&cb
    if len(shared)!=1:
        raise ValueError(f'expected unique shared color; got {shared}')
    c=next(iter(shared))
    mode_a=Counter(x for row in a for x in row).most_common(1)[0][0]
    mode_b=Counter(x for row in b for x in row).most_common(1)[0][0]
    if c==mode_a and c==mode_b:
        return [[3 if (a[i][j]!=c or b[i][j]!=c) else c for j in range(len(a[0]))] for i in range(len(a))]
    else:
        return [[3 if (a[i][j]==c and b[i][j]==c) else c for j in range(len(a[0]))] for i in range(len(a))]

